import { readFileSync, writeFileSync, mkdirSync, readdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT = join(__dirname, '../ghl-dist');
mkdirSync(OUT, { recursive: true });

const distDir = join(__dirname, '../dist/assets');
const distAssets = readdirSync(distDir);
const cssFile = distAssets.find((f) => f.endsWith('.css'));
const RAW = cssFile ? readFileSync(join(distDir, cssFile), 'utf-8') : '';
let css = RAW;
const bs = css.indexOf('html{scroll-behavior');
if (bs > 0) css = css.substring(bs);
const pe = css.indexOf('html{scroll-behavior');
if (pe > 0) css = css.substring(pe);

const FONT = `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,300;12..96,400;12..96,500;12..96,600;12..96,700&family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&display=swap" rel="stylesheet">`;
const STYLE = `<style>\n${css}\n</style>`;
const SJ = `(function(){var K='gh-reduce-motion';function r(){var s=localStorage.getItem(K);if(s!==null)return s==='1';return window.matchMedia('(prefers-reduced-motion: reduce)').matches;}function a(){document.documentElement.classList.toggle('reduce-motion',r());}a();window.ghToggleMotion=function(b){var n=!r();localStorage.setItem(K,n?'1':'0');a();document.querySelectorAll('[data-gh-motion-toggle]').forEach(function(t){t.setAttribute('aria-pressed',n)});};})();`;

