function servicesHTML() {
  const layerArticles = LAYERS.map((l,i) => 
    `<article class="scroll-mt-28" aria-labelledby="layer-${l.id}"><div class="flex items-baseline gap-4 mb-6"><span class="font-display text-4xl text-brand-500/30 font-semibold" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="grid place-items-center w-12 h-12 rounded-xl bg-brand-500 text-white shrink-0">${ic(l.icon,24)}</span><div><h3 id="layer-${l.id}" class="font-display text-2xl md:text-3xl font-medium text-ink">${l.name}</h3><p class="text-ink-muted text-sm mt-0.5">${l.short}</p></div></div><ul class="grid sm:grid-cols-2 gap-3 border-t border-surface-line pt-6">${l.items.map(it=>`<li class="flex items-start gap-3">${ic('check',20)}<span class="text-ink-soft text-base leading-relaxed">${it}</span></li>`).join('')}</ul></article>`
  ).join('\n');
  const archBtns = LAYERS.map(l => `<button type="button" data-arch="${l.id}" class="flex flex-col items-center gap-3 p-5 rounded-xl border transition-all bg-dark-mid/50 border-white/10 hover:border-brand-300/40"><span class="grid place-items-center w-12 h-12 rounded-xl bg-white/5 text-brand-300">${ic(l.icon,24)}</span><span class="text-white text-xs font-medium text-center leading-tight">${l.name.split(' & ')[0]}</span></button>`).join('');
  const indCards = INDUSTRIES.map(([icon,label]) => `<div class="flex items-center gap-3 p-4 rounded-xl border border-surface-line bg-surface/50">${ic(icon,20)}<span class="text-ink-soft text-sm font-medium">${label}</span></div>`).join('');
  return wrap('gh-services','Services',`<main id="main">
<section class="bg-dark-deep text-white pt-28 md:pt-36 pb-16 md:pb-20 relative overflow-hidden"><div class="absolute inset-0 opacity-50" aria-hidden="true"><div class="absolute top-20 left-1/3 w-80 h-80 bg-brand-500/15 blur-3xl rounded-full"></div></div><div class="relative container-gh max-w-3xl"><p class="text-sm text-brand-300 mb-4">Services</p><h1 class="font-display text-4xl sm:text-5xl md:text-6xl font-medium tracking-tight mb-5 text-measure">One connected system, built around how you already work.</h1><p class="text-lg text-white/75 leading-relaxed text-measure-tight">Four layers — CRM, automation, AI assistance and your website — that talk to each other. We set them up, import your data, and train you to run them.</p></div><div class="relative container-gh mt-14 hidden md:block"><div class="relative rounded-2xl bg-dark-mid/40 border border-white/10 p-10"><div class="grid grid-cols-4 gap-4">${archBtns}</div><div class="mt-6 flex items-center justify-center gap-2 py-3 rounded-xl bg-brand-500/10 border border-brand-300/20"><div class="flex items-center gap-2 text-brand-300 text-sm font-medium"><span class="w-2 h-2 rounded-full bg-brand-400 animate-pulseSoft" aria-hidden="true"></span>All connected through one Growth Hub workspace</div></div></div></div></section>
<section class="bg-surface py-20 md:py-28" aria-labelledby="layers-h"><div class="container-gh"><h2 id="layers-h" class="sr-only">Service layers</h2><div class="grid lg:grid-cols-[200px_1fr] gap-10"><nav class="hidden lg:block" aria-label="Service layers"><ul class="sticky top-28 space-y-1 border-l border-surface-line" id="gh-layer-nav">${LAYERS.map(l=>`<li><button type="button" data-scroll="${l.id}" class="block pl-4 py-2.5 text-sm font-medium border-l-2 -ml-px transition-colors text-left w-full border-transparent text-ink-muted hover:text-ink">${l.name}</button></li>`).join('')}</ul></nav><div class="space-y-16 md:space-y-24">${layerArticles}<article class="scroll-mt-28" aria-labelledby="addons-h"><div class="flex items-baseline gap-4 mb-6"><span class="font-display text-4xl text-brand-500/30 font-semibold" aria-hidden="true">05</span><span class="grid place-items-center w-12 h-12 rounded-xl bg-brand-500/10 text-brand-600 shrink-0">${ic('plus',24)}</span><div><h3 id="addons-h" class="font-display text-2xl md:text-3xl font-medium text-ink">Optional add-ons</h3><p class="text-ink-muted text-sm mt-0.5">Available when you need them</p></div></div><ul class="flex flex-wrap gap-2.5 border-t border-surface-line pt-6">${ADDONS.map(a=>`<li class="px-4 py-2.5 rounded-lg bg-white border border-surface-line text-ink-soft text-sm font-medium">${a}</li>`).join('')}</ul></article></div></div></div></section>
<section class="bg-white py-20 md:py-28" aria-labelledby="who-h"><div class="container-gh max-w-4xl"><p class="text-sm text-brand-600 mb-3">Who we work with</p><h2 id="who-h" class="font-display text-3xl sm:text-4xl font-medium tracking-tight text-ink mb-4">Startups, small businesses and established companies.</h2><p class="text-ink-muted text-lg mb-10 text-measure-tight">If you talk to customers, book appointments and send follow-ups, the system fits. We work across industries:</p><div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">${indCards}</div></div></section>
${cta("Tell us what you're running on.","Book a free one-hour consultation. We'll look at your current setup and show you exactly what each layer would replace.",{secondaryLabel:'See pricing',secondaryTo:'/pricing'})}
</main>${mobileBar()}`, `document.querySelectorAll('[data-scroll]').forEach(function(b){b.addEventListener('click',function(){var el=document.querySelector('[aria-labelledby="layer-'+b.getAttribute('data-scroll')+'"]');if(el)el.scrollIntoView({behavior:'smooth',block:'start'});});});var obs=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){var id=e.target.getAttribute('aria-labelledby').replace('layer-','');document.querySelectorAll('[data-scroll]').forEach(function(b){if(b.getAttribute('data-scroll')===id){b.className='block pl-4 py-2.5 text-sm font-medium border-l-2 -ml-px transition-colors text-left w-full border-brand-500 text-brand-600';}else{b.className='block pl-4 py-2.5 text-sm font-medium border-l-2 -ml-px transition-colors text-left w-full border-transparent text-ink-muted hover:text-ink';}});}});},{rootMargin:'-30% 0px -50% 0px',threshold:0});LAYERS.forEach(function(l){var el=document.querySelector('[aria-labelledby="layer-'+l.id+'"]');if(el)obs.observe(el);});`);
}

