function savingsJS() {
  return `
var APPS=${JSON.stringify(APPS.map(a=>({name:a[0],category:a[1],price:a[2]})))};
var PRESETS=${JSON.stringify(PRESETS)};
var GHP=${GHP};
var selected=new Set([0,6,7]);
var presetName=null;
function fmt(n){return '$'+Math.round(n).toLocaleString('en-US');}
function tween(el,from,to,dur){dur=dur||500;var start=performance.now();function step(now){var t=Math.min(1,(now-start)/dur);var v=from+(to-from)*(1-Math.pow(1-t,3));el.firstChild.textContent=fmt(v);if(t<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
var prevM=0,prevY=0,prevSM=0,prevSY=0;
function update(){
  var mt=0;selected.forEach(function(i){mt+=APPS[i].price;});
  var yt=mt*12,ms=Math.max(0,mt-GHP),ys=ms*12;
  var mEl=document.getElementById('gh-monthly'),yEl=document.getElementById('gh-yearly'),smEl=document.getElementById('gh-save-mo'),syEl=document.getElementById('gh-save-yr');
  tween(mEl,prevM,mt);tween(yEl,prevY,yt);prevM=mt;prevY=yt;
  smEl.firstChild.textContent=fmt(ms);syEl.textContent=fmt(ys)+' per year';
  document.getElementById('gh-live-count').textContent=selected.size+' of 23 selected';
  var list=document.getElementById('gh-selected-list');list.innerHTML='';
  Array.from(selected).forEach(function(i){var li=document.createElement('li');li.className='flex items-center justify-between text-xs text-white/60';li.innerHTML='<span class="truncate">'+APPS[i].name+'</span><span class="tabular-nums">$'+APPS[i].price+'</span>';list.appendChild(li);});
  document.querySelectorAll('[data-app]').forEach(function(b){var i=+b.getAttribute('data-app');var on=selected.has(i);b.setAttribute('aria-pressed',on);b.className='relative text-left p-3.5 rounded-xl border transition-all '+(on?'bg-brand-500/15 border-brand-400 shadow-[0_0_18px_rgba(5,150,105,0.2)]':'bg-dark-mid/60 border-white/10 hover:border-brand-300/30');var ck=b.querySelector('[data-check]');ck.className='grid place-items-center w-5 h-5 rounded-md shrink-0 transition-colors '+(on?'bg-brand-400 text-dark-deep':'border border-white/20');ck.innerHTML=on?'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6 9 17l-5-5"/></svg>':'';var pr=b.querySelector('[data-price]');pr.className='text-sm font-display font-semibold mt-2 '+(on?'text-brand-300':'text-white/50');});
}
document.querySelectorAll('[data-app]').forEach(function(b){b.addEventListener('click',function(){var i=+b.getAttribute('data-app');if(selected.has(i))selected.delete(i);else selected.add(i);presetName=null;document.querySelectorAll('[data-preset]').forEach(function(p){p.setAttribute('aria-pressed','false');p.className='px-3.5 py-2 rounded-lg text-sm font-medium border transition-colors bg-white/5 text-white/70 border-white/10 hover:border-brand-300/40 hover:text-white';});update();});});
document.querySelectorAll('[data-preset]').forEach(function(b){b.addEventListener('click',function(){var name=b.getAttribute('data-preset');var p=PRESETS.find(function(x){return x[0]===name;});selected=new Set(p[1]);presetName=(name==='Select all'||name==='Clear')?name:name;document.querySelectorAll('[data-preset]').forEach(function(x){x.setAttribute('aria-pressed','false');x.className='px-3.5 py-2 rounded-lg text-sm font-medium border transition-colors bg-white/5 text-white/70 border-white/10 hover:border-brand-300/40 hover:text-white';});b.setAttribute('aria-pressed','true');b.className='px-3.5 py-2 rounded-lg text-sm font-medium border transition-colors bg-brand-500 text-white border-brand-500';update();});});
update();
// Checkup
var CK=${JSON.stringify(CHECKUP)},RES=${JSON.stringify(RESULTS)};
var qi=0,answers=[],showResult=false;
function renderProgress(){var p=document.getElementById('gh-progress');p.innerHTML='';for(var i=0;i<CK.length;i++){var s=document.createElement('span');s.className='h-1.5 rounded-full transition-all '+(i<=qi?'w-8 bg-brand-500':'w-4 bg-surface-line');p.appendChild(s);}}
function renderQ(){if(showResult){renderResult();return;}document.getElementById('gh-q-label').textContent='Question '+(qi+1)+' of '+CK.length;renderProgress();document.getElementById('gh-q-text').textContent=CK[qi][0];var oc=document.getElementById('gh-q-options');oc.innerHTML='';CK[qi][1].forEach(function(opt,oi){var btn=document.createElement('button');btn.type='button';btn.className='flex items-center justify-between gap-3 p-4 rounded-xl border border-surface-line bg-white hover:border-brand-500 hover:bg-brand-50/40 transition-colors text-left group';btn.innerHTML='<span class="text-ink text-base font-medium">'+opt+'</span>'+function(){return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="text-brand-500 opacity-0 group-hover:opacity-100 transition-opacity"><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg>'}();btn.onclick=function(){answers[qi]=CK[qi][2][oi];if(qi<CK.length-1){qi++;renderQ();}else{showResult=true;renderResult();}};oc.appendChild(btn);});document.getElementById('gh-back-btn').style.display=qi>0?'block':'none';}
function renderResult(){var total=answers.reduce(function(a,b){return a+b;},0);var ri=total<=3?0:total<=6?1:2;var r=RES[ri];var c=document.getElementById('gh-checkup');c.innerHTML='<div class="animate-fadeUp" role="status"><span class="text-sm text-brand-600">Your result</span><h3 class="font-display text-3xl font-medium text-ink mt-2 mb-4">'+r[0]+'</h3><p class="text-ink-muted text-lg leading-relaxed mb-6">'+r[1]+'</p><div class="flex flex-col sm:flex-row gap-3"><a href="/contact#book" class="btn-primary">'+r[2]+' <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg></a><button type="button" id="gh-reset" class="btn-ghost"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg> Start over</button></div></div>';document.getElementById('gh-reset').onclick=function(){qi=0;answers=[];showResult=false;restoreCheckup();renderQ();};}
function restoreCheckup(){var c=document.getElementById('gh-checkup');c.innerHTML='<div class="flex items-center justify-between mb-6"><span class="text-sm text-ink-muted" aria-live="polite" id="gh-q-label"></span><div class="flex gap-1.5" aria-hidden="true" id="gh-progress"></div></div><h3 class="font-display text-2xl font-medium text-ink mb-6" id="gh-q-text"></h3><div class="flex flex-col gap-3" role="group" id="gh-q-options"></div><button type="button" id="gh-back-btn" class="mt-5 text-sm text-ink-muted hover:text-brand-600 transition-colors" style="display:none">Back</button>';document.getElementById('gh-back-btn').onclick=function(){if(qi>0){qi--;renderQ();}};}
document.addEventListener('DOMContentLoaded',function(){var bb=document.getElementById('gh-back-btn');if(bb)bb.onclick=function(){if(qi>0){qi--;renderQ();}};renderQ();});
`;
}

