function pricingJS() {
  return `
var PLANS=${JSON.stringify(PLANS.map(p=>({name:p.name,monthly:p.monthly})))};
var annual=false;
function fmt(n){return '$'+Math.round(n).toLocaleString('en-US');}
function updateBilling(){
  PLANS.forEach(function(p){var el=document.querySelector('[data-price="'+p.name+'"]');var price=annual?Math.round(p.monthly*0.8):p.monthly;el.innerHTML='$'+price+'<span class="text-sm text-white/50 font-normal">/mo</span>';var billEl=document.querySelector('[data-billing="'+p.name+'"]');billEl.textContent=annual?'billed annually':'billed monthly';});
  var mo=document.getElementById('gh-bill-mo'),yr=document.getElementById('gh-bill-yr');
  mo.setAttribute('aria-pressed',!annual);yr.setAttribute('aria-pressed',annual);
  mo.className='px-4 py-2 rounded-lg text-sm font-medium transition-colors '+(!annual?'bg-brand-500 text-white':'text-white/60 hover:text-white');
  yr.className='px-4 py-2 rounded-lg text-sm font-medium transition-colors '+(annual?'bg-brand-500 text-white':'text-white/60 hover:text-white')+' Annual <span class="text-brand-300 ml-1">save 20%</span>';
  yr.innerHTML='Annual <span class="text-brand-300 ml-1">save 20%</span>';
}
document.getElementById('gh-bill-mo').onclick=function(){annual=false;updateBilling();};
document.getElementById('gh-bill-yr').onclick=function(){annual=true;updateBilling();};
function updateRev(){var c=+document.getElementById('rev-customers').value,v=+document.getElementById('rev-value').value;document.getElementById('rev-cust-val').textContent=c;document.getElementById('rev-val-val').textContent=fmt(v);document.getElementById('rev-monthly').textContent=fmt(c*v);document.getElementById('rev-yearly').textContent=fmt(c*v*12);}
window.updateRev=updateRev;
`;
}

